function norm(v){v=String(v).trim().toUpperCase().replace(/\s/g,'');if(/^R?\d{5}$/.test(v))v='R-'+v.replace(/^R/,'');if(/^DL?2611B$/.test(v.replace(/-/g,'')))v=LOT;return v;}
